#!/usr/bin/env bash
# Metrics-epoch (paper/live split + per-division epoch) — SELF-CONTAINED apply
# (OPERATOR runs; no scp). Stream from Desktop:
#   Get-Content $HOME\Desktop\meapply.sh -Raw|ssh azureuser@trading.jacksumner.com "tr -d '\r'|bash"
# Drift-gates prod==BASE, backs up *.bak-pre-metrics-epoch-2026-06-20, md5-verified
# atomic install of 2 display files (web/data.py + templates/division.html).
# NO restart, NO config, NO DB write. The split (correctness fix) takes effect at
# the next restart; the epoch stays "not set" until a single agent_state INSERT at
# the D1 cutover. Files are byte-confirmed a clean delta on prod.
set -euo pipefail
PROD="/home/azureuser/trading_corp"; cd "$PROD"
DATA="trading_corp/web/data.py"
HTML="trading_corp/web/templates/division.html"
BASE_DATA=3874f469d70d864a542afab34e823041
BASE_HTML=ca894995be2cc8481a12e5a2e61b1d85
TGT_DATA=dae49424521a0586adecb32ccf1da614
TGT_HTML=b6e23456a1cfcec484f41c5b3ce6e61e
BAK=.bak-pre-metrics-epoch-2026-06-20
echo "== drift-gate (prod must == BASE) =="
md5sum $DATA $HTML
[ "$(md5sum $DATA|awk '{print $1}')" = "$BASE_DATA" ] || { echo "ABORT: data.py drift"; exit 2; }
[ "$(md5sum $HTML|awk '{print $1}')" = "$BASE_HTML" ] || { echo "ABORT: division.html drift"; exit 2; }
echo "== backup =="
cp -n $DATA $DATA$BAK; cp -n $HTML $HTML$BAK
echo "== decode staged =="
base64 -d > "$DATA.menew" <<'B64DATA'
