echo "== validate staged (py_compile + jinja parse) =="
python3 -m py_compile "$DATA.menew"
python3 -c "import jinja2,pathlib; jinja2.Environment().parse(pathlib.Path('$HTML.menew').read_text(encoding='utf-8')); print('jinja parse OK')"
echo "== verify staged md5 == TARGET (b64 integrity) =="
[ "$(md5sum "$DATA.menew"|awk '{print $1}')" = "$TGT_DATA" ] || { echo "ABORT: data.py target mismatch"; rm -f "$DATA.menew" "$HTML.menew"; exit 3; }
[ "$(md5sum "$HTML.menew"|awk '{print $1}')" = "$TGT_HTML" ] || { echo "ABORT: html target mismatch"; rm -f "$DATA.menew" "$HTML.menew"; exit 3; }
echo "== atomic install =="
mv "$DATA.menew" "$DATA"; mv "$HTML.menew" "$HTML"
echo "== re-verify =="
md5sum $DATA $HTML
python3 -m py_compile $DATA
echo "== METRICS-EPOCH APPLIED (no restart, no config, no DB). Split activates at next restart; epoch stays UNSET until the D1-cutover agent_state INSERT. =="
